using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Windows.Forms;
using Microsoft.Win32;
using System.Reflection;
[assembly: AssemblyTitle("Monja Excel Reference Tracer Setup")]
[assembly: AssemblyVersion("1.0.2.0")]
internal static class Setup {
 const string State=@"Software\Monja\ReferenceTracer\Installation",UninstallKey=@"Software\Microsoft\Windows\CurrentVersion\Uninstall\Monja.ReferenceTracer";
 static readonly string Home=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Monja","ReferenceTracer");
 static string Runtime(){foreach(string root in new[]{Environment.GetFolderPath(Environment.SpecialFolder.CommonProgramFiles),Environment.GetFolderPath(Environment.SpecialFolder.CommonProgramFilesX86)}){string path=Path.Combine(root,"Microsoft Shared","VSTO","10.0","VSTOInstaller.exe");if(File.Exists(path))return path;}throw new InvalidOperationException("VSTO Runtimeが必要です / VSTO Runtime is required.\nhttps://www.microsoft.com/download/details.aspx?id=105673");}
 static int Run(string operation,string manifest,bool silent){var info=new ProcessStartInfo(Runtime(),operation+" \""+manifest+"\""+(silent?" /Silent":"")){UseShellExecute=false,CreateNoWindow=true};using(var process=Process.Start(info)){process.WaitForExit();return process.ExitCode;}}
 static void Check(){using(var key=Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\NET Framework Setup\NDP\v4\Full")){if(key==null||Convert.ToInt32(key.GetValue("Release",0))<528040)throw new InvalidOperationException(".NET Framework 4.8以降が必要です / .NET Framework 4.8 or later is required.");}Runtime();}
 static string Installed(){using(var key=Registry.CurrentUser.OpenSubKey(State))return key==null?null:key.GetValue("Manifest") as string;}
 static void CopyTree(string source,string target){Directory.CreateDirectory(target);foreach(string file in Directory.GetFiles(source))File.Copy(file,Path.Combine(target,Path.GetFileName(file)),true);foreach(string dir in Directory.GetDirectories(source))CopyTree(dir,Path.Combine(target,Path.GetFileName(dir)));}
 static void RemovePackage(string manifest){if(String.IsNullOrEmpty(manifest))return;string directory=Path.GetDirectoryName(Path.GetFullPath(manifest)),parent=Path.GetFullPath(Path.Combine(Home,"Packages"))+Path.DirectorySeparatorChar;if(!directory.StartsWith(parent,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Unexpected installation path");if(Directory.Exists(directory))Directory.Delete(directory,true);}
 static string PackageId(string source){using(var sha=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(Path.Combine(source,"Monja.vsto")))).Replace("-","").Substring(0,16);}
 static void Install(bool silent){Check();string source=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"payload");if(!File.Exists(Path.Combine(source,"Monja.vsto")))throw new FileNotFoundException("ZIP全体を展開してSetup.exeを起動してください / Extract the entire ZIP before running Setup.exe.");string old=Installed();string destination=Path.Combine(Home,"Packages",PackageId(source));CopyTree(source,destination);string manifest=Path.Combine(destination,"Monja.vsto");if(old!=null){int uninstall=Run("/Uninstall",old,silent);if(uninstall!=0)throw new InvalidOperationException("Previous version removal failed: "+uninstall);}int result=Run("/Install",manifest,silent);if(result!=0){int rollback=old==null?0:Run("/Install",old,true);if(!String.Equals(old,manifest,StringComparison.OrdinalIgnoreCase))RemovePackage(manifest);if(rollback!=0)throw new InvalidOperationException("Installation failed: "+result+"; previous version recovery: "+rollback+". Run the previous package again.");throw new InvalidOperationException("VSTO installation: "+result+"\n信頼確認で許可されない場合や組織で制限されている場合は導入できません。管理担当者にお問い合わせください。\nInstallation requires the Office trust decision and your organization's permission.");}Directory.CreateDirectory(Home);string executable=Path.Combine(Home,"Setup.exe");if(!String.Equals(Path.GetFullPath(Application.ExecutablePath),executable,StringComparison.OrdinalIgnoreCase))File.Copy(Application.ExecutablePath,executable,true);using(var key=Registry.CurrentUser.CreateSubKey(State))key.SetValue("Manifest",manifest);using(var key=Registry.CurrentUser.CreateSubKey(UninstallKey)){key.SetValue("DisplayName","もんじゃExcel参照トレーサー / Monja Excel Reference Tracer");key.SetValue("Publisher","First Success G.K.");key.SetValue("DisplayVersion","1.0.2");key.SetValue("UninstallString","\""+executable+"\" /uninstall");key.SetValue("NoModify",1);key.SetValue("NoRepair",1);}if(old!=null&&!String.Equals(old,manifest,StringComparison.OrdinalIgnoreCase))RemovePackage(old);}
 static void Uninstall(bool silent){Check();string manifest=Installed();if(manifest==null)throw new InvalidOperationException("このセットアップで導入された製品はありません / No installation made by this setup was found.");int result=Run("/Uninstall",manifest,silent);if(result!=0)throw new InvalidOperationException("VSTO uninstall: "+result);Registry.CurrentUser.DeleteSubKeyTree(UninstallKey,false);Registry.CurrentUser.DeleteSubKeyTree(State,false);RemovePackage(manifest);}
 [STAThread]static int Main(string[] args){bool remove=args.Contains("/uninstall"),silent=args.Contains("/silent");try{if(silent){if(remove)Uninstall(true);else Install(true);return 0;}Application.EnableVisualStyles();var form=new Form{Text="Monja Excel Reference Tracer",Width=610,Height=380,StartPosition=FormStartPosition.CenterScreen,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false};var text=new Label{Left=22,Top=20,Width=550,Height=180,Text="もんじゃExcel参照トレーサー\n\nWindows版Excel / .NET Framework 4.8 / VSTO Runtime\n現在のユーザーにのみインストールします。Node.jsは不要です。\n\n配布元とOfficeの信頼確認を確認してから許可してください。\n自己署名版は発行元の身元が第三者により確認されていません。\n\nPer-user installation. No Node.js required.\nReview the Office trust prompt. This package uses a self-signed certificate."};var install=new Button{Left=22,Top=220,Width=260,Height=40,Text="インストール / Install"};var uninstall=new Button{Left=300,Top=220,Width=260,Height=40,Text="削除 / Uninstall"};var status=new Label{Left=22,Top=280,Width=550,Height=45,Text="Excelを保存して終了してください / Save and close Excel."};Action<bool> perform=rem=>{install.Enabled=uninstall.Enabled=false;try{if(rem)Uninstall(false);else Install(false);status.Text=rem?"削除しました。言語設定は保持されます / Removed. Language preference retained.":"完了しました。Excelを起動してください / Installed. Start Excel.";}catch(Exception ex){MessageBox.Show(form,ex.Message,"Monja",MessageBoxButtons.OK,MessageBoxIcon.Warning);}finally{install.Enabled=uninstall.Enabled=true;}};install.Click+=(s,e)=>perform(false);uninstall.Click+=(s,e)=>perform(true);form.Controls.AddRange(new Control[]{text,install,uninstall,status});if(remove)form.Shown+=(s,e)=>perform(true);Application.Run(form);return 0;}catch(Exception ex){Console.Error.WriteLine(ex.Message);return 1;}}
}
